const splitWords = (txt) => {
  if (txt.includes(' ')) {
    return txt.split(/\s+/);
  } else if (txt.includes(',')) {
    return txt.split(',');
  } else {
    let count = 0;
    for (let i = 0; i < txt.length; i++) {
      const char = txt[i];
      if (char >= 'a' && char <= 'z') {
        const order = char.charCodeAt(0) - 97;
        if (order % 2 !== 0) {
          count++;
        }
      }
    }
    return count;
  }
};

