const intersection = (interval1, interval2) => {
  const start1 = interval1[0];
  const end1 = interval1[1];
  const start2 = interval2[0];
  const end2 = interval2[1];

  const intersectStart = Math.max(start1, start2);
  const intersectEnd = Math.min(end1, end2);

  if (intersectStart > intersectEnd) {
    return "NO";
  }

  const length = intersectEnd - intersectStart;

  const isPrime = (num) => {
    if (num <= 1) return false;
    for (let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
      if (num % i === 0) return false;
    }
    return true;
  };

  return isPrime(length) ? "YES" : "NO";
};

