const minPath = (grid, k) => {
  const n = grid.length;
  let minPathList = null;

  const directions = [
    [0, 1], [0, -1], [1, 0], [-1, 0]
  ];

  const solve = (r, c, currentPath) => {
    if (currentPath.length === k) {
      if (minPathList === null || comparePaths(currentPath, minPathList) < 0) {
        minPathList = [...currentPath];
      }
      return;
    }

    // Pruning: if current path is already lexicographically larger than minPathList, stop
    if (minPathList !== null) {
      for (let i = 0; i < currentPath.length; i++) {
        if (currentPath[i] > minPathList[i]) return;
        if (currentPath[i] < minPathList[i]) break;
      }
    }

    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
        currentPath.push(grid[nr][nc]);
        solve(nr, nc, currentPath);
        currentPath.pop();
      }
    }
  };

  const comparePaths = (a, b) => {
    for (let i = 0; i < k; i++) {
      if (a[i] < b[i]) return -1;
      if (a[i] > b[i]) return 1;
    }
    return 0;
  };

  // To optimize, we only start from cells that could potentially be the start of the min path.
  // The absolute minimum value in the grid is the best possible start.
  let minVal = Infinity;
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] < minVal) minVal = grid[r][c];
    }
  }

  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] === minVal) {
        solve(r, c, [grid[r][c]]);
      }
    }
  }

  return minPathList;
};

