const tri = (n) => {
  const memo = {};

  const getTri = (i) => {
    if (i === 0) return 1; // Based on example tri(3) = [1, 3, 2, 8], index 0 is 1
    if (i === 1) return 3;
    if (memo[i] !== undefined) return memo[i];

    if (i % 2 === 0) {
      memo[i] = 1 + i / 2;
    } else {
      // For odd n: tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
      // This is a recursive dependency on tri(n+1).
      // Since tri(n+1) is even, it can be solved directly: 1 + (n+1)/2
      memo[i] = getTri(i - 1) + getTri(i - 2) + getTri(i + 1);
    }
    return memo[i];
  };

  const result = [];
  for (let i = 0; i <= n; i++) {
    result.push(getTri(i));
  }
  return result;
};

